def has_4(r): return 4 in r[15:19]
def has_5(r): return 5 in r[5:8]
def has_8(r): return 8 in r[0:5]
def has_9(r): return 9 in r[10:15]
def c9(r): return sum(1 for v in r[10:15] if v == 9)
def c4(r): return sum(1 for v in r[15:19] if v == 4)

def transform_final(grid):
    result = []
    for row in grid:
        c9r = c9(row)
        has9 = has_9(row)
        has4 = has_4(row)
        has8 = has_8(row)
        has5 = has_5(row)

        if has9 and has4 and c9r >= 3:
            out = [9, 9, 9, 4]
        elif has9 and has4 and c9r == 2:
            out = [9, 4, 4, 4]
        elif has9 and has8 and has4 and has5 and c9r == 1:
            out = [9, 4, 4, 4]
        elif has9 and has8 and has4:
            out = [9, 9, 9, 4]  # Otherwise when 9+4 present
        elif has9 and has8 and not has4:
            out = [9, 9, 8, 9]
        elif has5 and has8 and has4:
            out = [5, 4, 4, 8]
        elif has9 and not has8 and not has4 and not has5:
            out = [9, 9, 9, 0]
        elif not has9 and has8 and has4:
            out = [9, 4, 4, 4]  # Fall back when no 9s
        else:
            out = [5, 5, 0, 0] if has5 else [6, 6, 0, 0]

        result.append(out)
    return result

print("=== Demo ===")
